package dev.wildcraft.test;
import net.fabricmc.fabric.api.client.gametest.v1.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
/** All real bow/lease modes and exits reuse the true native fixture; new layer is observed independently. */
public final class FocusLegRigClientTest implements FabricClientGameTest {
    @Override public void runTest(ClientGameTestContext c){c.runOnClient(v->FocusLegAudit.begin());try{new AirBowRigClientTest().runTest(c);exits(c);c.runOnClient(v->{if(FocusLegAudit.frames==0||FocusLegAudit.gpu==0||FocusLegAudit.partial==0||FocusLegAudit.full==0||FocusLegAudit.maxDelta<.005)throw new AssertionError("Actual current focus layer enter/full/skin/GPU evidence absent");System.out.println("C6R FOCUS legs frames="+FocusLegAudit.frames+" GPU="+FocusLegAudit.gpu+" partial="+FocusLegAudit.partial+" full="+FocusLegAudit.full+" actualDelta="+FocusLegAudit.maxDelta+" protected matrix and segment lengths PASS; real full/partial .20 exit envelope and native time-cost-shot ownership PASS");});}finally{c.runOnClient(v->{FocusLegAudit.enabled=false;FocusLegAudit.before=null;FocusLegAudit.partialAction=null;});}}
    private static void exits(ClientGameTestContext c){try(TestSingleplayerContext w=c.worldBuilder().create()){
        w.getConnection().waitForChunksRender();w.getServer().runCommand("gamemode survival @p");w.getServer().runOnServer(s->{for(int x=-8;x<=8;x++)for(int z=-8;z<=8;z++)s.overworld().setBlockAndUpdate(new net.minecraft.core.BlockPos(x,119,z),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());s.getPlayerList().getPlayers().getFirst().teleportTo(.5,120,.5);});c.waitFor(v->v.player.getY()>119);c.runOnClient(v->v.options.setCameraType(net.minecraft.client.CameraType.THIRD_PERSON_FRONT));
        for(boolean partial:new boolean[]{false,true}){
            AirBowRigClientTest.prepare(c,w,net.minecraft.world.entity.player.PlayerModelType.WIDE,net.minecraft.world.InteractionHand.MAIN_HAND);
            if(partial){c.runOnClient(v->{FocusLegAudit.partialExecuted=false;});w.getServer().runOnServer(server->FocusLegAudit.partialAction=()->server.execute(()->server.tickRateManager().setTickRate(20)));launch(c);c.waitFor(v->FocusLegAudit.partialExecuted);}else{AirBowRigClientTest.jumpUse(c);c.waitFor(v->{var pulse=GroundBowRigClientTest.state(v).getData(dev.wildcraft.client.animation.rig.FocusLegRig.PULSE);return pulse!=null&&pulse.weight()>.999;});w.getServer().runCommand("tick rate 20");}
            c.runOnClient(v->AirBowAudit.expectActive=false);c.waitFor(v->!dev.wildcraft.focus.FocusTime.active(v.player));
            var start=c.computeOnClient(v->GroundBowRigClientTest.state(v).getData(dev.wildcraft.client.animation.rig.FocusLegRig.PULSE));if(start==null||start.active())throw new AssertionError("Actual loss of native time ownership must start a visual exit on current live bow base");long begin=System.nanoTime();float age=start.age(),weight=start.weight();c.takeScreenshot("focus-leg-live-"+(partial?"partial":"full")+"-exit-current-weight");
            var stamina=new java.util.concurrent.atomic.AtomicReference<Double>();w.getServer().runOnServer(s->stamina.set(dev.wildcraft.player.PlayerStamina.get(s.getPlayerList().getPlayers().getFirst()).stamina()));
            c.waitFor(v->GroundBowRigClientTest.state(v).getData(dev.wildcraft.client.animation.rig.FocusLegRig.PULSE)==null);double elapsed=(System.nanoTime()-begin)/1e9;
            if(elapsed<.2-age-.04||elapsed>.2-age+.12)throw new AssertionError("Visual exit did not preserve actual .20 envelope: "+elapsed+" firstAge="+age);
            c.runOnClient(v->{if(!v.player.isUsingItem()||v.player.onGround()||AirBowRigClientTest.frame(v)==null||!AirBowRigClientTest.frame(v).clip().startsWith("bow_air_"))throw new AssertionError("Exit must finish over the same current real airborne bow, without keeping a frozen reference");});
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();if(s.tickRateManager().tickrate()!=20||dev.wildcraft.focus.FocusTime.active(p)||java.lang.Math.abs(dev.wildcraft.player.PlayerStamina.get(p).stamina()-stamina.get())>.00001||p.getInventory().getItem(10).getCount()!=32||p.getMainHandItem().getDamageValue()!=0||AirBowAudit.shots.get()!=0)throw new AssertionError("Body exit changed actual time/cost/shot/ammo/wear");});
            System.out.println("C6R actual external native rate ownership loss visual exit partial="+partial+" initialWeight="+weight+" elapsed="+elapsed+" current bow/normal time/no extra cost-shot PASS");c.takeScreenshot("focus-leg-live-"+(partial?"partial":"full")+"-exit-restored-current-base");c.getInput().releaseKey(v->v.keyUse);c.waitFor(v->v.player.onGround());
        }
        int strength=dev.wildcraft.client.focus.FocusOptions.get().strength;
        try{
            AirBowRigClientTest.prepare(c,w,net.minecraft.world.entity.player.PlayerModelType.WIDE,net.minecraft.world.InteractionHand.MAIN_HAND);c.runOnClient(v->dev.wildcraft.client.focus.FocusOptions.get().strength=0);AirBowRigClientTest.jumpUse(c);c.waitFor(v->{var pulse=GroundBowRigClientTest.state(v).getData(dev.wildcraft.client.animation.rig.FocusLegRig.PULSE);return pulse!=null&&pulse.weight()>.999;});
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();if(!dev.wildcraft.focus.FocusTime.active(p)||s.tickRateManager().tickrate()!=5)throw new AssertionError("Presentation-off must preserve actual native skill");});c.takeScreenshot("focus-leg-native-post-off-body-on");c.setScreen(()->new net.minecraft.client.gui.screens.PauseScreen(true));c.waitFor(v->v.isPaused());var frozen=c.computeOnClient(v->GroundBowRigClientTest.state(v).getData(dev.wildcraft.client.animation.rig.FocusLegRig.PULSE));if(frozen==null)throw new AssertionError("Actual paused leg layer missing");c.waitTicks(12);c.runOnClient(v->{var now=GroundBowRigClientTest.state(v).getData(dev.wildcraft.client.animation.rig.FocusLegRig.PULSE);if(now==null||java.lang.Math.abs(now.weight()-frozen.weight())>1e-6||java.lang.Math.abs(now.age()-frozen.age())>1e-6)throw new AssertionError("Paused focus layer envelope advanced");});c.takeScreenshot("focus-leg-native-pause-freeze");c.setScreen(()->null);c.getInput().releaseKey(v->v.keyUse);c.waitFor(v->v.player.onGround());
            AirBowRigClientTest.prepare(c,w,net.minecraft.world.entity.player.PlayerModelType.WIDE,net.minecraft.world.InteractionHand.MAIN_HAND);c.runOnClient(v->{FocusLegAudit.partialExecuted=false;FocusLegAudit.partialAction=()->{var client=net.minecraft.client.Minecraft.getInstance();AirBowAudit.expectActive=false;client.options.keyUse.setDown(false);client.gameMode.releaseUsingItem(client.player);};});launch(c);c.waitFor(v->FocusLegAudit.partialExecuted);c.getInput().releaseKey(v->v.keyUse);c.waitFor(v->!v.player.isUsingItem());if(c.computeOnClient(v->GroundBowRigClientTest.state(v).getData(dev.wildcraft.client.animation.rig.FocusLegRig.PULSE)!=null))throw new AssertionError("Early native release cannot retain old body for a visual fade");c.takeScreenshot("focus-leg-real-early-release-owner");c.waitFor(v->v.player.onGround());
        }finally{c.runOnClient(v->dev.wildcraft.client.focus.FocusOptions.get().strength=strength);}
    }finally{c.getInput().releaseKey(v->v.keyUse);c.runOnClient(v->{AirBowAudit.enabled=false;RigAudit.enabled=false;RigAudit.fixture=null;});}}

    private static void launch(ClientGameTestContext c){c.getInput().holdKey(v->v.keyJump);c.waitFor(v->!v.player.onGround());c.getInput().releaseKey(v->v.keyJump);c.getInput().holdKey(v->v.keyUse);c.waitFor(v->v.player.isUsingItem());}

}
